<script>(function(){
var prefills=<?=json_encode($prefills,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
var old=<?=json_encode($old,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
var form=document.getElementById('waste-legacy-create-form');
document.addEventListener('DOMContentLoaded',function(){if(form&&typeof window.initLinearTripForm==='function')window.initLinearTripForm(form);});
function setValue(name,value){var el=form.elements.namedItem(name);if(el)el.value=value==null?'':String(value);}
function syncDestination(){var d=form.querySelector('[data-waste-destination]'),f=form.querySelector('[data-waste-utilizer-field]'),u=f.querySelector('select');f.style.display=d.value==='utilizer'?'block':'none';u.required=d.value==='utilizer';}
function syncPlan(){var m=form.querySelector('[data-waste-plan-mode]'),e=form.querySelector('[data-waste-plan-exact]'),f=form.querySelector('[data-waste-plan-from]'),t=form.querySelector('[data-waste-plan-to]'),exact=m.value==='exact',range=m.value==='range';e.style.display=exact?'block':'none';e.required=exact;f.style.display=range?'block':'none';f.required=range;t.style.display=range?'block':'none';t.required=range;}
function setHint(name,text,warning){var el=form.querySelector('[data-legacy-hint="'+name+'"]');if(!el)return;el.textContent=text||'';el.classList.toggle('is-warning',!!warning);el.classList.toggle('is-note',!warning&&!!text);}
function fill(id,override){var s=prefills[id];if(!s)return;form.reset();form.action='<?=app_url('/company/trips/departures/legacy')?>/'+encodeURIComponent(id)+'/materialize';form.querySelector('[data-legacy-identity]').textContent='Рейс #'+id+' из старой базы будет создан в ERP с номером #'+id+'. Перед созданием проверьте данные.';
setValue('request_ids',(s.found_request_ids||[]).join(', '));setValue('planned_start_mode',s.planned_start_mode==='range'?'range':'exact');setValue('planned_start_date',s.planned_start_date);setValue('planned_start_date_from',s.planned_start_date_from);setValue('planned_start_date_to',s.planned_start_date_to);setValue('planned_finish_date','');setValue('actual_start_date',s.actual_start_date);setValue('actual_end_date',s.actual_end_date);setValue('comment',s.comment);setValue('status',s.actual_end_date?'completed':(s.actual_start_date?'in_progress':'searching_executor'));setValue('destination_type','utilizer');
var missing=(s.missing_request_ids||[]).map(function(x){return 'Заявка '+x+' из старой базы не найдена в ERP';});setHint('request_ids',missing.length?missing.join(' · '):'Заявки из старой БД предзаполнены. Состав можно изменить.',missing.length>0);
var noPlan=!s.planned_start_date&&!s.planned_start_date_from&&!s.planned_start_date_to;var planNotes=(s.notices||[]).filter(function(x){return x.indexOf('дат')>=0||x.indexOf('диапазон')>=0;});setHint('planned_start',planNotes.length?planNotes.join(' '):(noPlan?'Плановая дата в старой БД не заполнена. Укажите её перед созданием.':'Плановая дата предзаполнена и может быть изменена.'),false);
setHint('actual_start','',false);setHint('actual_end','',false);
var other=(s.warnings||[]);var notes=(s.notices||[]).filter(function(x){return planNotes.indexOf(x)<0;});form.querySelector('[data-legacy-other-warnings]').textContent=other.concat(notes).join(' · ');form.querySelector('[data-legacy-other-warnings]').classList.toggle('is-warning',other.length>0);
if(override){Object.keys(override).forEach(function(k){if(k!=='_legacy_id')setValue(k,override[k]);});}
syncDestination();syncPlan();var submit=form.querySelector('[data-waste-create-submit]');submit.disabled=String(form.elements.namedItem('request_ids').value||'').trim()==='';openModal('waste-trip-create-modal');}
async function preview(){var r=form.querySelector('[data-waste-preview-result]');r.textContent='Проверка...';try{var x=await fetch('<?=app_url('/company/trips/departures/preview')?>',{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}),p=await x.json();if(!x.ok||!p.success){r.textContent=p.message||('Проверьте заявки. Не найдены/недоступны: '+(p.missing||[]).join(', ')+'; заняты: '+Object.keys(p.occupied||{}).join(', '));return;}r.textContent='Найдено '+p.found_count+'/'+p.input_count+', '+Number(p.total_mass_kg||0).toLocaleString('ru-RU')+' кг, конфликтов нет.';}catch(e){r.textContent='Не удалось выполнить проверку. Сохранение всё равно выполнит серверную валидацию.';}}
form.querySelector('[data-waste-destination]').addEventListener('change',syncDestination);form.querySelector('[data-waste-plan-mode]').addEventListener('change',syncPlan);form.querySelector('[data-waste-preview]').addEventListener('click',preview);form.querySelector('[data-waste-request-ids]').addEventListener('input',function(){form.querySelector('[data-waste-create-submit]').disabled=this.value.trim()==='';});
document.querySelectorAll('[data-create-legacy]').forEach(function(el){var open=function(ev){if(ev&&ev.target.closest('a,button')&&ev.currentTarget!==ev.target.closest('button'))return;fill(Number(el.dataset.createLegacy),null);};el.addEventListener('click',open);el.addEventListener('keydown',function(ev){if((ev.key==='Enter'||ev.key===' ')&&el.tagName!=='BUTTON'){ev.preventDefault();fill(Number(el.dataset.createLegacy),null);}});});
<?php if($oldLegacyId>0):?>fill(<?=$oldLegacyId?>,old);<?php endif;?>
})();</script>
<?php endif;?>